-- Native800 G9 IMPORT/state-check only. No old RPC or source protocol is changed.
-- Service transport still requires the separately reviewed actual operator gates.
create schema private_fcf_native800;
revoke all on schema private_fcf_native800 from public,anon,authenticated,service_role;
create function private_fcf_native800.score_state(cid bigint)returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
 with scope as(select array(select id from rounds where competition_id=cid order by id)rids,array(select id from players where competition_id=cid order by id)pids),actual as(select coalesce(jsonb_agg(to_jsonb(ps)order by to_jsonb(ps)::text collate "C"),'[]'::jsonb)rows from player_scores ps cross join scope s where ps.round_id=any(s.rids)or ps.player_id=any(s.pids))
 select jsonb_build_object('competitionId',cid,'roundIds',to_jsonb(s.rids),'playerIds',to_jsonb(s.pids),'count',jsonb_array_length(a.rows),'snapshotText',a.rows::text,'snapshotSha256',encode(sha256(convert_to(a.rows::text,'UTF8')),'hex'))||case when cid=797 then jsonb_build_object('roundCounts',(select jsonb_agg(jsonb_build_object('roundId',r.id,'scoreRows',(select count(*)from player_scores ps where ps.round_id=r.id),'priceChangeRows',(select count(*)from price_changes pc where pc.round_id=r.id))order by r.id)from rounds r where r.competition_id=797))else '{}'::jsonb end from scope s cross join actual a
$$;
