create function private_fcf_native800.humans(p jsonb)returns void language plpgsql stable security definer set search_path=public,pg_temp as $$begin
 perform private_fcf_six_target_release.require(p#>>'{native,dependencies,complete}'='true'and p#>>'{native,dependencies,competitionUserRows}'='0'and not exists(select 1 from jsonb_each((p->>'dependencySnapshotText')::jsonb->'relations')x where x.value->'globalUser'='true'::jsonb and x.value->>'count'<>'0')and not exists(select 1 from jsonb_array_elements(p#>'{native,dependencies,rounds}')r where r->>'lineupRows'<>'0'or r->>'rosterRows'<>'0'or r->>'transferRows'<>'0'or r->>'chipRows'<>'0')and not exists(select 1 from jsonb_array_elements(p#>'{native,dependencies,matches}')m where m->>'userRows'<>'0'),'closed actual human/fantasy0, distinct from nonhuman strict round counters');
end$$;
create function private_fcf_native800.selected_scores()returns void language plpgsql stable security definer set search_path=public,pg_temp as $$begin
 perform private_fcf_native800.scoring_guard();
 perform private_fcf_six_target_release.require(not exists(with expected as(select ap.round_id,ap.player_id,sum(ap.points)points from appearance_points ap where ap.round_id in(select id from rounds where competition_id=797)group by ap.round_id,ap.player_id),actual as(select ps.round_id,ps.player_id,ps.points from player_scores ps where ps.round_id in(select id from rounds where competition_id=797)or ps.player_id in(select id from players where competition_id=797))(select *from expected except all select *from actual)union all(select *from actual except all select *from expected)),'independent full selected postimport score rederivation under unchanged authoritative rules');
end$$;
create function private_fcf_native800.guard_before(v jsonb,p jsonb)returns void language plpgsql stable security definer set search_path=public,pg_temp as $$declare scores jsonb:=private_fcf_native800.score_state(797);q jsonb;begin
 perform private_fcf_native800.scoring_guard();perform private_fcf_native800.humans(p);perform private_fcf_six_target_release.require((((v->>'targetPacketText')::jsonb)->>'auditedUTC')::timestamptz between clock_timestamp()-interval'5 minutes'and clock_timestamp(),'fresh original readonly preparation for first write only');
