 perform private_fcf_six_target_release.require(not exists(select 1 from jsonb_array_elements((scores->>'snapshotText')::jsonb)s where not exists(select 1 from rounds r where r.id=(s->>'round_id')::bigint and r.competition_id=797)or not exists(select 1 from players p where p.id=(s->>'player_id')::bigint and p.competition_id=797)),'unexpected cross-scope selected score row');
 for q in select value from jsonb_array_elements(scores->'roundCounts')loop
  perform private_fcf_six_target_release.require(exists(select 1 from jsonb_array_elements(p#>'{native,dependencies,rounds}')r where r->'roundId'=q->'roundId'and(r->>'userRows')::bigint=(q->>'scoreRows')::bigint+(q->>'priceChangeRows')::bigint),'literal strict round count equals actual nonhuman score/price rows; never subtract unknown rows');
 end loop;
end$$;
create function private_fcf_native800.guard_after(v jsonb)returns void language plpgsql stable security definer set search_path=public,pg_temp as $$declare p jsonb;before jsonb:=(v->>'nativeSnapshotText')::jsonb;begin
 perform private_fcf_six_target_release.require((select count(*)from private_fcf_future_target_release.receipts where competition_id=797)<=1,'no unexpected additional target receipt rows');
 perform private_fcf_native800.scoring_guard();perform private_fcf_native800.source_binding(v->'inventoryBinding',((v->>'targetPacketText')::jsonb)#>'{target,fixtures}');
 perform private_fcf_six_target_release.require(not exists(select 1 from jsonb_array_elements(((v->>'targetPacketText')::jsonb)#>'{target,fixtures}')f where f->>'statisticsStatus'='pending'and clock_timestamp()-((f->>'date')::date::timestamp at time zone'UTC')between interval'-1 day'and interval'14 days'and(f#>>'{source,capturedUTC}')::timestamptz<clock_timestamp()-interval'1 hour'),'pending provider freshness still valid at final state boundary');
 perform private_fcf_six_target_release.require(private_fcf_native800.score_state(783)=v#>'{scoreBeforeimages,offTargetG1}','off-target G1 full score rows/count/scope/TEXT/SHA preserved byte-identically');
 perform private_fcf_native800.selected_scores();
 p:=private_fcf_future_projection.capture('es-ct-tercera-g9',array(select jsonb_array_elements_text(((v->>'targetPacketText')::jsonb)#>'{databaseInventory,identityPrivacy,checkedKeys}')));perform private_fcf_native800.humans(p);
 perform private_fcf_six_target_release.require(not exists(select 1 from jsonb_each(before->'relations')b where b.key not in('public.players','public.matches','public.rounds','public.appearances','public.goals','public.player_scores','public.statistika_igralcev','private_fcf_six_target_release.club_bindings','private_fcf_future_target_release.receipts')and b.value is distinct from((p->>'dependencySnapshotText')::jsonb)#>array['relations',b.key]),'all non-owned protected relation counts/hashes remain exact');
end$$;

-- Frozen authoritative view SELECT from20260928100000; temporary compiler view only.
create view private_fcf_native800._reviewed_points as
select
  a.id as appearance_id,
  a.match_id,
  a.player_id,
  m.round_id,
  p.position,
  a.minutes_played,
  a.goals,
  coalesce(asi.st, 0) as assists,
  a.clean_sheet,
  a.goals_conceded,
  tocke_za_nastop(
    p.position, a.minutes_played, a.goals, coalesce(asi.st, 0)::int,
    pr.cista, pr.prejeti, a.penalties_saved, a.penalties_missed,
    a.own_goals, a.yellow_cards, a.red_cards,
    zm.zmaga, r.pravila_tockovanja
  ) as points,
  zm.zmaga,
  pr.prejeti as prejeti_na_igriscu,
  pr.cista as cista_mreza,
  r.pravila_tockovanja as pravila
from appearances a
join matches m on m.id = a.match_id
join rounds r on r.id = m.round_id
join players p on p.id = a.player_id
left join lateral (
  select count(*)::int as st
  from goals g
  where g.match_id = a.match_id and g.assist_player_id = a.player_id
) asi on true
cross join lateral (
  select case when a.team_id = m.home_team_id then m.home_goals > m.away_goals
              else m.away_goals > m.home_goals end as zmaga
) zm
-- Goli, ki jih je igralčeva ekipa prejela, ko je bil na igrišču. Gol v
-- minuti menjave velja za igralca, ki odhaja; kdor igra do konca, dobi tudi
-- gole v sodniškem podaljšku. Če goli niso popolni (manjka minuta ali jih je
-- manj kot po izidu), ostane izid cele tekme — kakor pri različici 1.
left join lateral (
  select count(*) filter (where g.minute is null) as brez_minute,
         count(*) as vseh,
         count(*) filter (where g.minute > a.minute_on
                            and (g.minute <= a.minute_off or a.minute_off >= 90)) as na_igriscu
  from goals g
  where r.pravila_tockovanja >= 2
    and g.match_id = a.match_id
    -- avtogol je zapisan pri ekipi strelca in šteje nasprotniku
    and (case when g.is_own_goal then g.team_id = a.team_id
              else g.team_id <> a.team_id end)
) gl on true
cross join lateral (
  select r.pravila_tockovanja >= 2
         and gl.brez_minute = 0 and gl.vseh = a.goals_conceded as po_golih
) po
cross join lateral (
  select case when po.po_golih then gl.na_igriscu::int else a.goals_conceded end as prejeti,
         case when po.po_golih then gl.na_igriscu = 0 else a.clean_sheet end as cista
) pr;
