-- Import-state check only. Price/calendar/legal15/launch are deliberately absent.
create function public.fcf_native800_check(p_rollout_text text,p_sha256 text,p_activate boolean,p_stage_text text,p_stage_sha256 text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v jsonb;r private_fcf_future_target_release.receipts%rowtype;begin
 perform private_fcf_six_target_release.require(p_activate is false,'native800 activation permanently held until separately reviewed cut3');
 perform private_fcf_six_target_release.require(octet_length(p_rollout_text)between 2 and 8388608,'bounded native800 rollout');perform private_fcf_six_target_release.lock_target(797);perform private_fcf_future_import.lock_dependencies();
 v:=private_fcf_native800.validate(p_rollout_text,p_sha256);perform private_fcf_native800.stage_attestation(p_stage_text,p_stage_sha256,v,'check',p_sha256);
 select *into r from private_fcf_future_target_release.receipts where competition_id=797;perform private_fcf_six_target_release.require(r.stage='imported'and r.rollout_text=p_rollout_text and r.rollout_sha256=p_sha256 and r.packet_sha256=v->>'targetPacketSha256'and r.source_fingerprint=v#>>'{inventoryBinding,sourceFingerprintSha256}'and r.imported_state_sha256=private_historical_statistics.state_sha256(797)and not(select active from competitions where id=797),'exact original committed import/state; UNKNOWN requires readback, never a blind retry');
 perform private_fcf_six_target_release.no_target_users(797);perform private_fcf_six_target_release.privacy(797);perform private_fcf_six_target_release.compare_canonical(797);perform private_fcf_native800.guard_after(v);perform private_fcf_native800.stage_attestation(p_stage_text,p_stage_sha256,v,'check',p_sha256);
 return jsonb_build_object('schemaVersion',1,'kind','fcf-native800-import-state-check','stage','imported','targetSlug','es-ct-tercera-g9','receiptId',r.id::text,'rolloutSha256',p_sha256,'canonicalVerified',true,'admissible',false,'nativeAdmission',false,'activationEligible',false);
end$$;
create function public.fcf_native800_receipt(p_slug text)returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare r private_fcf_future_target_release.receipts%rowtype;v jsonb;begin
 perform private_fcf_six_target_release.require(p_slug='es-ct-tercera-g9','fixed native800 G9 receipt only');perform private_fcf_six_target_release.require((select count(*)from private_fcf_future_target_release.receipts where competition_id=797)<=1,'single native800 receipt only; extras stay HOLD');select *into r from private_fcf_future_target_release.receipts where competition_id=797;if r.id is null then return null;end if;v:=r.rollout_text::jsonb;
 perform private_fcf_native800.selected_scores();
 perform private_fcf_six_target_release.require(v->>'kind'='fcf-native800-import-rollout'and v->>'protocol'='fcf-native800-v1'and v->>'targetSlug'=p_slug and r.stage='imported'and not(select active from competitions where id=797)and r.rollout_sha256=encode(sha256(convert_to(r.rollout_text,'UTF8')),'hex')and r.packet_sha256=encode(sha256(convert_to(r.packet_text,'UTF8')),'hex')and r.imported_state_sha256=private_historical_statistics.state_sha256(797)and v#>'{scoreBeforeimages,offTargetG1}'=private_fcf_native800.score_state(783),'exact native800 committed receipt/current state/G1 preservation readback; drift stays HOLD');
 return jsonb_build_object('schemaVersion',1,'kind','fcf-native800-import-receipt','receiptId',r.id::text,'competitionId',797,'targetSlug',p_slug,'stage',r.stage,'rolloutText',r.rollout_text,'rolloutSha256',r.rollout_sha256,'targetPacketSha256',r.packet_sha256,'sourceFingerprintSha256',r.source_fingerprint,'importedStateSha256',r.imported_state_sha256,'currentStateSha256',private_historical_statistics.state_sha256(797),'currentActive',false,'canonicalVerified',false,'admissible',false,'nativeAdmission',false,'activationEligible',false);
end$$;
